export function translate(language, key, values = {}) {
  const text = language === 'he' ? (hebrew[key] ?? key) : key;
  return text.replace(/\{(\w+)\}/g, (match, name) => Object.hasOwn(values, name) ? String(values[name]) : match);
}

export function locale(language) { return language === 'he' ? 'he-IL' : 'en-US'; }

export function dayLabel(day, language) {
  return new Intl.DateTimeFormat(locale(language), { weekday: 'short' }).format(new Date(`${day}T12:00:00`));
}
